/* MIT. Controller-facing scene adapter; no automatic world activation here. */
#ifndef MYRO_CAMPAIGN_SCENE_UI200_H
#define MYRO_CAMPAIGN_SCENE_UI200_H
#include "campaign_scene200.h"
#include "campaign_career200.h"
#include "npc_editor55.h"
typedef struct{Scene200 scene;unsigned page,choice,lastNode,role,confirmRole,superReview,careerJob,guildReview,guildError;NpcEditor55 guildEditor;char lines[8][96];int count;}SceneUI200;
static SceneUI200 campaignUI200;
static void scene_ui_release200(void){scene_close200(&campaignUI200.scene);memset(&campaignUI200,0,sizeof(campaignUI200));}
static int scene_file_read200(void*context,unsigned at,unsigned char*out,unsigned bytes){FILE*f=context;return at<=CHAPTER1_FILE_BYTES200&&bytes<=CHAPTER1_FILE_BYTES200-at&&!fseek(f,at,SEEK_SET)&&fread(out,1,bytes,f)==bytes;}
static int scene_ui_open_bounded200(NpcState55*state,unsigned ceiling){
#ifdef MYRO_HOST
 const char*path=getenv("MYRO_CHAPTER1_PATH");if(!path)path="../Campaign/chapter1-scenes.bin";
#else
 const char*path="D:\\chapter1.bin";
#endif
 FILE*f=fopen(path,"rb");if(!f)return 0;int valid=!fseek(f,0,SEEK_END)&&ftell(f)==CHAPTER1_FILE_BYTES200;int ok=valid&&scene_open_bounded200(&campaignUI200.scene,state,scene_file_read200,f,ceiling);fclose(f);if(ok){campaignUI200.page=campaignUI200.choice=campaignUI200.confirmRole=campaignUI200.superReview=0;campaignUI200.lastNode=~0u;}return ok;
}
static int scene_ui_open200(NpcState55*state){return scene_ui_open_bounded200(state,CAMPAIGN_RELEASE_SCENES193);}
static const char*scene_ui_text200(SceneUI200*u,const Campaign200*c,char out[512]){const char*text=scene_text200(&u->scene,1),*at=strstr(text,"{GUILD}");if(!at)return text;snprintf(out,512,"%.*s%s%s",(int)(at-text),text,c->guild,at+7);return out;}
static int scene_ui_tick200(void){SceneUI200*u=&campaignUI200;int status=scene_poll200(&u->scene);if(u->scene.data){Campaign200 c;if(campaign_load200(u->scene.state,&c)!=1)return SC200_ERROR;if(c.checkpoint!=u->lastNode){u->lastNode=c.checkpoint;u->page=u->choice=0;char text[512];u->count=ui_wrap(scene_ui_text200(u,&c,text),u->lines,372,1);if(status==SC200_GUILD){memset(&u->guildEditor,0,sizeof(u->guildEditor));u->guildEditor.string=1;u->guildReview=u->guildError=0;}}}return status;}
static int scene_ui_modal200(void){int status=scene_ui_tick200();Campaign200 c;return status==SC200_GUILD||status==SC200_LINE||status==SC200_CHOICE||status==SC200_ROLE||(status==SC200_WAIT&&campaignUI200.scene.state&&campaign_load200(campaignUI200.scene.state,&c)==1&&c.cursor==1);}
/* Caller supplies its actual native job; this layer never grants a job. */
static int scene_ui_input200(unsigned pressed,unsigned actualJob){SceneUI200*u=&campaignUI200;u->careerJob=actualJob;unsigned verifiedLineage=campaign_verified_career200(u->scene.state,actualJob);int status=scene_ui_tick200();if(!scene_ui_modal200())return status;if(status==SC200_GUILD){if(u->guildReview){if(pressed&4){u->guildReview=0;return status;}if(pressed&2){if(campaign_guild200(u->scene.state,u->guildEditor.text)){u->guildReview=0;return scene_ui_tick200();}u->guildError=2;}return status;}if(u->guildEditor.length>=24&&(pressed&2)&&u->guildEditor.choice<npc_editor_count55(&u->guildEditor)-1)pressed&=~2u;int action=npc_editor_input55(&u->guildEditor,pressed);if(action==2){scene_ui_release200();return SC200_CLOSED;}if(action==1){unsigned length=u->guildEditor.length;if(!length||length>24||u->guildEditor.text[0]==' '||u->guildEditor.text[length-1]==' ')u->guildError=1;else{u->guildError=0;u->guildReview=1;}}return status;}if(pressed&4){if(u->superReview){u->superReview=0;return status;}if(u->confirmRole){u->confirmRole=0;return status;}scene_ui_release200();return SC200_CLOSED;}if(status==SC200_WAIT){if((pressed&16)&&actualJob==0)u->superReview=1;if((pressed&2)&&u->superReview&&campaign_super_intent200(u->scene.state,actualJob))u->superReview=0;}else if(status==SC200_LINE){unsigned pages=(u->count+3)/4;if(!pages)pages=1;if((pressed&4096)&&u->page)u->page--;if(pressed&2){if(u->page+1<pages)u->page++;else scene_next200(&u->scene,0);}}else if(status==SC200_CHOICE){if(pressed&(1024|2048))u->choice^=1;if(pressed&2)scene_next200(&u->scene,u->choice);}else if(status==SC200_ROLE){if(!u->confirmRole){if(pressed&1024)u->role=(u->role+2)%3;if(pressed&2048)u->role=(u->role+1)%3;if((pressed&2)&&verifiedLineage)u->confirmRole=1;}else if((pressed&2)&&verifiedLineage){if(campaign_commit_role200(u->scene.state,u->role+1,verifiedLineage))u->confirmRole=0;}}int after=scene_ui_tick200();if(after==SC200_WAIT&&u->scene.cursor>=3){scene_ui_release200();return SC200_CLOSED;}return after;}
static void scene_guild_draw200(void){SceneUI200*u=&campaignUI200;if(u->guildReview){ui_panel(110,164,420,156,"Put this name in the ledger?",0,-1);ui_fit47(132,201,376,1,u->guildEditor.text);ui_scaled(132,231,.9f,"Your guild is yours to lead.");if(u->guildError==2)ui_scaled(132,253,.85f,"The name could not be saved. Please try again.");ui_hint64(132,290,.85f,"A: ink it in   B: reconsider");return;}NpcEditor55*e=&u->guildEditor;unsigned count=npc_editor_count55(e),rows=(count+9)/10;int height=118+rows*20,top=(480-height)/2;ui_panel(120,top,400,height,"Name your guild",0,-1);ui_fit47(136,top+28,368,1,e->text);for(unsigned k=0;k<count;k++){int x=136+(int)(k%10)*36,y=top+60+(int)(k/10)*20;ui_cell(x,y,34,19,k==e->choice);if(k==count-1)ui_scaled(x+3,y+2,.8f,"OK");else ui_scaled(x+5,y+2,.8f,"%c",npcEditorKeys55[k]);}if(u->guildError)ui_scaled(136,top+height-45,.8f,"Use 1-24 characters, with no edge spaces.");ui_hint64(134,top+height-25,.8f,"A: type  X: erase  Y: review  B: cancel");}
static void scene_ui_draw200(void){SceneUI200*u=&campaignUI200;int status=scene_ui_tick200();if(!scene_ui_modal200())return;if(status==SC200_GUILD){scene_guild_draw200();return;}int height=status==SC200_WAIT?166:status==SC200_ROLE?166:status==SC200_CHOICE?114:54+(u->count>4?4:u->count)*17;if(height<78)height=78;int y=456-height;ui_panel(120,y,400,height,status==SC200_ROLE?"Choose your story role":scene_text200(&u->scene,0),0,-1);if(status==SC200_WAIT){if(u->superReview){ui_scaled(134,y+26,1,"Choose the Super Novice story path?");ui_scaled(134,y+49,1,"Your job remains Novice until its normal quest.");ui_scaled(134,y+72,1,"The story can continue while you train.");ui_hint64(134,y+118,.85f,"A: accept intent   B: reconsider");}else{ui_scaled(134,y+26,1,"Complete your chosen first-job examination.");ui_scaled(134,y+49,1,"Return here when your job has changed.");if(u->careerJob==0)ui_hint64(134,y+90,.85f,"Y: Super Novice path");ui_hint64(134,y+118,.85f,"B: return to your examination");}}else if(status==SC200_LINE){for(int n=0;n<4&&u->page*4+n<(unsigned)u->count;n++)ui_scaled(134,y+23+n*17,1,"%s",u->lines[u->page*4+n]);ui_hint64(134,456-22,.8f,"A: continue   B: close");}else if(status==SC200_CHOICE){for(unsigned n=0;n<2;n++){ui_cell(129,y+24+n*30,382,28,u->choice==n);ui_fit47(136,y+28+n*30,365,1,scene_text200(&u->scene,2+n));}ui_hint64(134,434,.8f,"UP/DOWN: answer   A: choose   B: close");}else if(u->confirmRole){ui_scaled(134,y+27,1,"This career and story role become permanent.");ui_scaled(134,y+52,1,"Advancement still follows your normal job quests.");ui_hint64(134,y+110,.85f,"A: confirm role   B: reconsider");}else{static const char*roles[]={"Melee - Vanguard","Ranged - Pathfinder","Support - Keeper"};for(unsigned n=0;n<3;n++){ui_cell(129,y+24+n*28,382,26,u->role==n);ui_scaled(136,y+28+n*28,1,"%s",roles[n]);}ui_hint64(134,434,.8f,"UP/DOWN: role   A: review   B: close");}}
#endif
